import{_ as a,o,c as e,a2 as r}from"./chunks/framework.A5mep7Fe.js";const u=JSON.parse('{"title":"💰 05 · 薪资爆料与行业洞察","description":"","frontmatter":{},"headers":[],"relativePath":"10-职业发展与资源/05-薪资爆料与行业洞察.md","filePath":"10-职业发展与资源/05-薪资爆料与行业洞察.md","lastUpdated":1786806808000}'),l={name:"10-职业发展与资源/05-薪资爆料与行业洞察.md"};function d(i,t,n,s,h,c){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="💰-05-·-薪资爆料与行业洞察" tabindex="-1">💰 05 · 薪资爆料与行业洞察 <a class="header-anchor" href="#💰-05-·-薪资爆料与行业洞察" aria-label="Permalink to &quot;💰 05 · 薪资爆料与行业洞察&quot;">​</a></h1><blockquote><p>薪资与趋势的「社区共识」参考（非官方、存在显著个体差异与时效，务必结合自身判断）。目的是帮你建立「市场水位」认知，而非精确数字。</p></blockquote><hr><h2 id="一、薪资区间参考-极粗略-2024-2026-社区口径" tabindex="-1">一、薪资区间参考（极粗略，2024-2026 社区口径） <a class="header-anchor" href="#一、薪资区间参考-极粗略-2024-2026-社区口径" aria-label="Permalink to &quot;一、薪资区间参考（极粗略，2024-2026 社区口径）&quot;">​</a></h2><blockquote><p>⚠️ 以下为「年总包（Base×12+奖金+股票）」量级参考，受城市/学历/经验/公司/年份影响极大。</p></blockquote><table tabindex="0"><thead><tr><th>层级</th><th>算法岗（参考）</th><th>开发/应用岗（参考）</th></tr></thead><tbody><tr><td>校招本科</td><td>较入门区间</td><td>较入门区间</td></tr><tr><td>校招硕士</td><td>中高区间</td><td>中区间</td></tr><tr><td>校招博士/顶会</td><td>高区间（研究岗）</td><td>—</td></tr><tr><td>社招 3-5 年</td><td>高区间</td><td>中高区间</td></tr><tr><td>资深/专家</td><td>很高区间</td><td>很高区间</td></tr></tbody></table><ul><li><strong>AI 应用开发</strong>近年溢价明显（供需失衡）</li><li><strong>Agent/RAG 方向</strong>岗位增长快，薪资上行</li><li>独角兽期权波动大，需看兑现路径</li></ul><blockquote><p>具体数字极易过时，<strong>建议用 Levels.fyi / 牛客薪资帖 / offer 谈薪反推当前水位</strong>，本表只给「量级感」。</p></blockquote><h2 id="二、行业趋势洞察-跨周期视角" tabindex="-1">二、行业趋势洞察（跨周期视角） <a class="header-anchor" href="#二、行业趋势洞察-跨周期视角" aria-label="Permalink to &quot;二、行业趋势洞察（跨周期视角）&quot;">​</a></h2><ol><li><strong>从「训模型」到「用模型」</strong>：应用层岗位（RAG/Agent/平台）需求增速 &gt; 纯研究岗</li><li><strong>推理时计算崛起</strong>：o1/R1 类推理模型开辟新能力维度</li><li><strong>端侧/私有化</strong>：数据合规推动端侧与私有部署岗位</li><li><strong>多模态统一</strong>：视觉/语音/文本融合岗位增多</li><li><strong>AI 原生应用</strong>：新一批「AI 原生」产品与公司涌现，机会在「场景深耕」</li></ol><h2 id="三、给求职者的建议" tabindex="-1">三、给求职者的建议 <a class="header-anchor" href="#三、给求职者的建议" aria-label="Permalink to &quot;三、给求职者的建议&quot;">​</a></h2><ul><li>别只盯薪资，看「能力复利 + 平台 + 业务前景」</li><li>早期用大厂/头部历练，中期看总包与稳定</li><li>保持对 L4 前沿的嗅觉，但把时间投入 L0/L1/L2</li><li>行业有周期，练好底层能力是穿越周期的根本</li></ul><h2 id="四、高频追问" tabindex="-1">四、高频追问 <a class="header-anchor" href="#四、高频追问" aria-label="Permalink to &quot;四、高频追问&quot;">​</a></h2><p><strong>Q：AI 岗薪资还会涨吗？</strong></p><blockquote><p>结构性分化：应用/稀缺方向（Agent/端侧/多模态）需求强；纯「套壳」岗位会内卷。整体看，懂落地的人比纯算法更稀缺，溢价持续。</p></blockquote><p><strong>Q：现在入行晚不晚？</strong></p><blockquote><p>不晚。AI 应用落地才刚开始，行业远未定型。关键是「用对路线 + 扎实能力」，而非入场时间。早入有先发，晚入有更成熟的学习资源（如本项目）。</p></blockquote><hr><p>➡️ 返回：<a href="./README">10-职业发展与资源 README</a> ｜ 进入：<a href="./../面试真题集/README">面试真题集</a></p>',19)])])}const p=a(l,[["render",d]]);export{u as __pageData,p as default};
